def unit_of_work(metadata=None, timeout=None):
    if timeout is not None:
        timeout = float(timeout)
    else:
        timeout = neo4j.get_default_timeout()

    def decorator(func):
        def wrapper(*args, **kwargs):
            with neo4j.Transaction(func, timeout=timeout, metadata=metadata) as tx:
                result = func(*args, **kwargs)
            return result
        return wrapper
    return decorator

