def format(self, sql, params):
    # Convert the SQL query to use out-style parameters
    out_style_params = {}
    if self.in_style == SQLParamStyle.NAMED:
        for param, value in params.items():
            out_style_params[":%s" % param] = value
    elif self.in_style == SQLParamStyle.ORDINAL:
        for i, value in enumerate(params):
            out_style_params[":%d" % (i + 1)] = value
    else:
        raise ValueError("Invalid SQL parameter style: %s" % self.in_style)

    # Replace the in-style parameters with out-style parameters in the SQL query
    for param in out_style_params.keys():
        sql = sql.replace(param, out_style_params[param])

    return sql, out_style_params

