def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    # Parse the image href to extract the image ID and the URL scheme
    if not image_href or (len(image_href) < 10):
        raise ValueError("The image href must be a non-empty string at least 10 characters long.")

    image_id = image_href[1:] # The image ID is everything after the '#' character
    netloc = image_href[:image_href.find('#')] # The URL scheme is everything before the '#' character
    use_ssl = netloc.startswith('https') # True if the URL scheme is https, False otherwise
    return (image_id, netloc, use_ssl)

