class AnsiblePlaybook(object):
    def __init__(self, ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
        self._ir_workspace = ir_workspace
        self._ir_plugin = ir_plugin
        self._playbook_path = playbook_path
        self._verbose = verbose
        self._extra_vars = extra_vars or {}
        self._ansible_args = ansible_args or {}

    def run(self):
        ansible_playbook_args = [self._playbook_path]
        if self._verbose:
            ansible_playbook_args.append('-' + self._verbose)
        if self._extra_vars:
            ansible_playbook_args.extend(('--extra-vars', str(self._extra_vars)))
        if self._ansible_args:
            ansible_playbook_args.extend(('--' + key, str(value)) for key, value in self._ansible_args.items())
        self._ir_workspace.run(self._ir_plugin.get_venv_python(), 'ansible-playbook', *ansible_playbook_args)
